// 후보가 0건이면 「subject 별로 분리」에서 흐름이 끊겨 요약이 안 돈다.
// Run Once for All Items 는 처리 모드지 빈 입력 실행 보장이 아니다 —
// 앞에서 명시적으로 분기해 이리로 보낸다.
return [{ json: { __zero_candidates: true } }];

// ─────────────────────────────────────────────────────────────────────────
// 클러스터링 렌더링 — subject 하나가 한 콜
// 실행 모드: Run Once for Each Item
// 입력: 「subject 별로 분리」 (n >= 2 인 것만 여기로 온다)
// ─────────────────────────────────────────────────────────────────────────

const P = $('GET cluster prompt').first().json;

// 기사를 한 줄에 하나씩 JSON 으로. 프롬프트가 그 형식을 전제한다
const articlesJson = $json.articles.map((a) => JSON.stringify(a)).join('\n');

const VALUES = {
  SUBJECT_NAME: $json.subject_name ?? '',
  N: String($json.articles.length),
  ARTICLES_JSON: articlesJson,
};
const TOKEN = /\[\[([A-Z_]+)\]\]/g;

const counts = {};
for (const t of P.user_template.matchAll(TOKEN)) counts[t[1]] = (counts[t[1]] || 0) + 1;
for (const k of Object.keys(VALUES)) {
  if (counts[k] !== 1) throw new Error(`user_template 의 [[${k}]] 가 ${counts[k] || 0}번`);
}
const unknown = Object.keys(counts).filter((k) => !(k in VALUES));
if (unknown.length) throw new Error(`모르는 자리표시자: ${unknown.join(', ')}`);

// 한 번의 정규식 치환. 순차 치환하면 본문에 다른 자리표시자 문자열이
// 들어 있을 때 재치환된다
const userPrompt = P.user_template.replace(TOKEN, (w, k) => (k in VALUES ? VALUES[k] : w));

return {
  json: {
    batch_id: $('POST batch start').first().json.id,
    subject_id: $json.subject_id,
    subject_name: $json.subject_name,
    n: $json.articles.length,
    aids: $json.articles.map((a) => a.aid),
    system_prompt: P.system_prompt,
    user_prompt: userPrompt,
  },
};

// ─────────────────────────────────────────────────────────────────────────
// n = 1 subject — 코드가 singleton 이슈를 만든다
// 실행 모드: Run Once for Each Item
//
// 근거는 비용이 아니라 층위다. 기사가 하나뿐이면 판단할 경우의 수가 없다 —
// 결과는 반드시 singleton 하나다. **판단이 존재하지 않는 자리는 LLM 에
// 맡기지 않는다.** "셀 수 있는 건 코드가 센다"의 연장이다.
//
// **새 의미를 만들어내지 않는다.** 한 기사밖에 없다는 사실 자체가 묶인
// 이유라, 코드가 문장을 새로 짓거나 LLM 을 한 번 더 부를 이유가 없다.
// ─────────────────────────────────────────────────────────────────────────

const a = $json.articles[0];

return {
  json: {
    subject_id: $json.subject_id,
    subject_name: $json.subject_name,
    issue_signal: a.issue_signal,   // 기사 분석 결과 그대로
    article_ids: [a.aid],
    cluster_reason: a.summary,      // 그대로
    source: 'code',
  },
};

// ─────────────────────────────────────────────────────────────────────────
// 클러스터링 출력 검증 — 이슈를 펼친다
// 실행 모드: Run Once for All Items
// 입력: 「클러스터 AI」 출력만 (코드 singleton 은 합치기 뒤에서 들어온다)
//
// **AI 노드 출력에는 subject_id 가 없다.** 에이전트가 아이템을 통째로
// 갈아치우기 때문이다. 그래서 subject_id 로 원본을 찾으면 못 찾고, 모든
// aid 가 unknown 이 되어 12개 subject 전부 partition_broken 이 났다.
// 인덱스로 맞춘다 — 에이전트는 입력 하나당 출력 하나를 낸다.
// 코드 singleton 을 먼저 합치면 순서가 섞여 인덱스도 못 쓴다.
//
// 완전 분할을 여기서 1차로 잡는다. 최종 판정은 collector 가
// candidate_snapshot 기준으로 하지만, 소재 콜을 30번 더 쓰기 전에
// 걸러내는 게 싸다.
// ─────────────────────────────────────────────────────────────────────────

const src = $('클러스터 렌더링').all();
const out = [];

$input.all().forEach((item, i) => {
  const j = item.json;
  const meta = (src[i] && src[i].json) || {};

  if (meta.subject_id === undefined) {
    out.push({ json: { __skip: true, reject: 'meta_lost',
      detail: `인덱스 ${i} 의 렌더링 원본을 못 찾았다 (렌더 ${src.length}건 · AI ${$input.all().length}건)` }});
    return;
  }

  if (j.error !== undefined) {
    out.push({ json: { __skip: true, subject_id: meta.subject_id,
      reject: 'agent_error',
      detail: String((j.error && j.error.message) || j.error).slice(0, 200) }});
    return;
  }

  const body = j.output ?? j;
  const issues = body && body.issues;
  if (!Array.isArray(issues) || issues.length === 0) {
    out.push({ json: { __skip: true, subject_id: meta.subject_id,
      reject: 'no_issues', detail: JSON.stringify(body).slice(0, 120) }});
    return;
  }

  const expected = new Set(meta.aids || []);
  const seen = new Set();
  let bad = null;

  for (const it of issues) {
    const ids = it && it.article_ids;
    if (!Array.isArray(ids) || ids.length === 0) { bad = 'empty_article_ids'; break; }
    for (const aid of ids) {
      // 없는 aid 를 지어내지 마라 — 프롬프트가 명시한다
      if (!expected.has(aid)) { bad = `unknown_aid:${aid}`; break; }
      if (seen.has(aid)) { bad = `duplicate_aid:${aid}`; break; }
      seen.add(aid);
    }
    if (bad) break;
    if (typeof it.issue_signal !== 'string' || !it.issue_signal.trim()) {
      bad = 'empty_issue_signal'; break;
    }
  }
  // 누락. 자동 보정하지 않는다 — 보정하면 LLM 이 완전 분할을 지켰는지
  // 검증할 수 없고, 빠진 기사가 다른 기사와 묶여야 했던 건지
  // singleton 이어야 했던 건지 코드는 알 수 없다
  if (!bad && seen.size !== expected.size) {
    bad = `missing_aids:${[...expected].filter((x) => !seen.has(x)).join(',')}`;
  }

  if (bad) {
    out.push({ json: { __skip: true, subject_id: meta.subject_id,
      reject: 'partition_broken', detail: bad }});
    return;
  }

  for (const it of issues) {
    out.push({ json: {
      subject_id: meta.subject_id,
      subject_name: meta.subject_name,
      issue_signal: it.issue_signal.trim(),
      article_ids: it.article_ids,
      cluster_reason: (it.reason || '').trim() || null,
      source: 'llm',
    }});
  }
});

return out;

// ─────────────────────────────────────────────────────────────────────────
// 소재 생성 렌더링 — 이슈 하나가 한 콜
// 실행 모드: Run Once for Each Item
//
// 기사 수·매체 수를 **주지 않는다.** System Prompt 가 그 둘을 점수에
// 반영하지 말라고 하는데 라벨까지 붙여 입력으로 주면 축이 침범된다(#37).
//   business_relevance = 서비스 직접성
//   hot_*              = 열도 (코드가 센다)
// ─────────────────────────────────────────────────────────────────────────

const P = $('GET compose prompt').first().json;

// 이슈에 속한 기사 본문값을 후보 응답에서 되찾는다
const cand = $('GET candidates').first().json;
const byAid = {};
for (const g of cand.subjects) for (const a of g.articles) byAid[a.aid] = a;

const articles = $json.article_ids.map((aid) => {
  const a = byAid[aid] || {};
  return { aid, press: a.press, published_at: a.published_at,
           title: a.title, summary: a.summary };
});

const VALUES = {
  SUBJECT_NAME: $json.subject_name ?? '',
  ISSUE_SIGNAL: $json.issue_signal ?? '',
  CLUSTER_REASON: $json.cluster_reason ?? '',
  ARTICLES_JSON: articles.map((a) => JSON.stringify(a)).join('\n'),
};
const TOKEN = /\[\[([A-Z_]+)\]\]/g;

const counts = {};
for (const t of P.user_template.matchAll(TOKEN)) counts[t[1]] = (counts[t[1]] || 0) + 1;
for (const k of Object.keys(VALUES)) {
  if (counts[k] !== 1) throw new Error(`user_template 의 [[${k}]] 가 ${counts[k] || 0}번`);
}
const unknown = Object.keys(counts).filter((k) => !(k in VALUES));
if (unknown.length) throw new Error(`모르는 자리표시자: ${unknown.join(', ')}`);

const userPrompt = P.user_template.replace(TOKEN, (w, k) => (k in VALUES ? VALUES[k] : w));

return {
  json: {
    subject_id: $json.subject_id,
    subject_name: $json.subject_name,
    issue_signal: $json.issue_signal,
    article_ids: $json.article_ids,
    cluster_reason: $json.cluster_reason,
    cluster_source: $json.source,
    system_prompt: P.system_prompt,
    user_prompt: userPrompt,
  },
};

// ─────────────────────────────────────────────────────────────────────────
// 소재 출력 검증 — /complete 요청 본문의 topic 하나로
// 실행 모드: Run Once for Each Item
//
// 형식만 본다. 소속·중복·누락·subject 는 collector 가 candidate_snapshot
// 기준으로 판정한다 — 여기서 흉내내면 기준이 둘이 된다.
// ─────────────────────────────────────────────────────────────────────────

const src = $('소재 렌더링').item.json;

const base = {
  subject_id: src.subject_id,
  issue_signal: src.issue_signal,
  article_ids: src.article_ids,
  cluster_reason: src.cluster_reason,
};

function fail(reject, detail) {
  return { json: { ...base, __skip: true, reject,
                   detail: String(detail).slice(0, 150) }};
}

if ($json.error !== undefined) {
  const e = $json.error;
  return fail('agent_error', (e && (e.message || e.description)) || e);
}

const out = $json.output ?? $json;
if (out === null || typeof out !== 'object') return fail('not_an_object', typeof out);

const title = typeof out.title === 'string' ? out.title.trim() : '';
const summary = typeof out.summary === 'string' ? out.summary.trim() : '';
const rationale = typeof out.rationale === 'string' ? out.rationale.trim() : '';
if (!title) return fail('empty_title', JSON.stringify(out).slice(0, 80));
if (!summary) return fail('empty_summary', '');
if (!rationale) return fail('empty_rationale', '');

const br = out.business_relevance;
if (typeof br !== 'number' || !(br >= 0 && br <= 1)) {
  return fail('business_relevance_out_of_range', br);
}

// 검색량 공급원이 없다. volume 을 지어내면 축이 침범된 것이다 —
// keywords 는 문자열 배열만 받는다
const kw = Array.isArray(out.keywords)
  ? out.keywords.filter((k) => typeof k === 'string' && k.trim())
                .map((k) => k.trim())
  : [];

return { json: { ...base, title, summary, keywords: kw,
                 business_relevance: br, rationale }};

// ─────────────────────────────────────────────────────────────────────────
// /complete 요청 본문 조립
// 실행 모드: Run Once for All Items
//
// 전부 아니면 전무다. 형식 검증에서 하나라도 걸리면 **보내지 않는다** —
// 보내봤자 collector 가 누락으로 422 를 낼 뿐이고, 그러면 원인이
// "형식 실패"인지 "LLM 이 기사를 빠뜨림"인지 섞인다.
// ─────────────────────────────────────────────────────────────────────────

const items = $input.all().map((i) => i.json || {});
const skipped = items.filter((j) => j.__skip === true);
const topics = items.filter((j) => !j.__skip);

const batchId = $('POST batch start').first().json.id;

if (skipped.length) {
  const t = {};
  for (const s of skipped) { const k = s.reject || 'unknown'; t[k] = (t[k] || 0) + 1; }
  return [{ json: { __abort: true, batch_id: batchId,
    reason: 'compose_validation_failed',
    skipped: skipped.length, reasons: t,
    samples: skipped.slice(0, 5).map((s) => ({
      issue_signal: s.issue_signal, reject: s.reject, detail: s.detail })) }}];
}

return [{ json: { batch_id: batchId, topics } }];

// ─────────────────────────────────────────────────────────────────────────
// 배치 요약 — 상위 워크플로가 완료를 읽는 단일 지점
// 실행 모드: Run Once for All Items
// ─────────────────────────────────────────────────────────────────────────

const items = $input.all().map((i) => i.json || {});
const zero = items.find((j) => j.__zero_candidates === true);
const abort = items.find((j) => j.__abort === true);
const done = items.find((j) => j.ok === true || j.n_topics !== undefined);
const err = items.find((j) => j.error !== undefined || (j.detail && j.detail.error));

let clusterSkipped = 0, clusterReasons = {}, nIssues = 0, nCode = 0;
try {
  for (const it of $('이슈 검증').all()) {
    const j = it.json;
    if (j.__skip) { clusterSkipped++; const k = j.reject || 'unknown';
                    clusterReasons[k] = (clusterReasons[k] || 0) + 1; }
    else { nIssues++; if (j.source === 'code') nCode++; }
  }
} catch (e) {}

let cand = {};
try {
  const c = $('GET candidates').first().json;
  cand = { n_articles: c.n_articles, n_subjects: c.n_subjects,
           n_llm_calls: c.n_llm_calls };
} catch (e) {}

const base = {
  stage: 'topics',
  batch_id: (() => { try { return $('POST batch start').first().json.id; }
                    catch (e) { return null; } })(),
  candidates: cand,
  n_issues: nIssues,
  n_issues_from_code: nCode,          // n=1 subject. 판단 없는 자리는 코드가
  cluster_skipped: clusterSkipped,
  cluster_reasons: clusterReasons,
  finished_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
};

if (zero) return [{ json: { ...base, ok: true, reason: 'no_candidates' } }];

if (abort) {
  return [{ json: { ...base, ok: false, reason: abort.reason,
    compose_skipped: abort.skipped, compose_reasons: abort.reasons,
    samples: abort.samples } }];
}

if (done && done.ok) {
  return [{ json: { ...base, ok: clusterSkipped === 0,
    n_topics: done.n_topics, n_consumed: done.n_articles,
    n_stale: done.n_stale, batch_state: done.state } }];
}

// collector 가 422 로 거부한 경우
const d = (err && (err.detail || err)) || {};
return [{ json: { ...base, ok: false,
  reason: d.reason || d.error || 'complete_failed',
  rejected: (d.rejected || []).slice(0, 20) } }];
